import{_ as s,a0 as a,w as p,s as u,ao as n,I as i,x as l,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"編寫對社區真正有用的文檔 | LCTT x X-CMD","titleTemplate":false,"description":"編寫對社區真正有用的文檔 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"編寫對社區真正有用的文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"編寫對社區真正有用的文檔 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230316.3 ⭐️⭐️ Write documentation that actually works for your community","title":"編寫對社區真正有用的文檔","tag":"202304","desc":""},"relativePath":"202304/20230316.3 ⭐️⭐️ Write documentation that actually works for your community.md","filePath":"[post].md"}'),m={name:"202304/20230316.3 ⭐️⭐️ Write documentation that actually works for your community.md"};function d(f,t,g,T,x,b){const o=a("Link");return p(),u("div",null,[t[27]||(t[27]=n('<h1 id="編寫對社區真正有用的文檔" tabindex="-1">編寫對社區真正有用的文檔 <a class="header-anchor" href="#編寫對社區真正有用的文檔" aria-label="Permalink to “編寫對社區真正有用的文檔”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/22/172758mm2rzjry2ful090y.jpg" alt=""></p><blockquote><p>建立良好的文檔可能是困難的，但它對有效的溝通至關重要。遵循這個框架來編寫並與正確的人分享文檔。</p></blockquote><p>成功和可持續的項目，與那些消失無蹤的項目有什麼不同？答案是 —— 社區。社區是開源項目的發展動力，而文檔是構建社區的基石之一。也就是説，文檔的意義不僅僅在於文檔本身。</p><p>建立好的文檔可能很困難。用户不願意閲讀文檔，因為它不易查找，它很快就過時了，它冗長，或者它不全面。</p><p>開發團隊不寫文檔，因為他們陷入了“對我來説顯而易見，所以對所有人都顯而易見”的陷阱。他們不寫，因為他們忙於開發項目。要麼是需求變化太快了，要麼是開發得還不夠快。</p><p>但是好的文檔仍然是團隊和項目之間最好的溝通工具。考慮到項目隨着時間的推移往往會變得更大，這一點尤其重要。</p><p>文檔可以是團隊或公司內部的唯一真理。這在協調人們朝着共同的目標前進，以及在人們轉移到不同的項目時保留知識方面非常重要。</p><p>那麼，要如何為一個項目寫出合適的文檔，並與正確的人分享呢？</p><h3 id="什麼是成功的社區文檔" tabindex="-1">什麼是成功的社區文檔？ <a class="header-anchor" href="#什麼是成功的社區文檔" aria-label="Permalink to “什麼是成功的社區文檔？”">​</a></h3><p>要想在你的社區文檔編寫中取得成功，你需要：</p><ul><li>規劃你的路徑</li><li>使其清晰簡單</li><li>靈活變通，根據具體情況調整路徑</li><li>做版本控制</li></ul><p><img src="https://opensource.com/sites/default/files/2023-03/documentationflowchart.png" alt="圖片展示了建立文檔的整個流程"></p><p>靈活並不意味着混亂。許多項目之所以成功，就是因為它們組織得很好。</p><p>James Clear（《<ruby>原子習慣<rt>Atomic Habits</rt></ruby>》一書的作者）寫道：“你並不是提升到了你目標所在的水平，而是降低到你整個系統所在的水平。”一定要組織好過程，使水平足夠高，才能取得成功。</p><h3 id="設計流程" tabindex="-1">設計流程 <a class="header-anchor" href="#設計流程" aria-label="Permalink to “設計流程”">​</a></h3><p>文檔本身就是一個項目。你可以把寫文檔當作寫代碼一樣。事實上，文檔可以是一個產品，而且是一個非常有價值的產品。</p><p>這就意味着你可以採用與軟件開發相同的流程：分析、獲取需求、設計、實現和維護，把文檔作為你的一個流程對待。</p><p>在設計流程時，要從不同的角度考慮。不是所有的文檔都適用於所有人。</p><p>大多數用户只需要一個瞭解項目概況的文檔，而 API 文檔則是留給開發者或高級用户的。</p><p>開發者需要了解庫和函數的文檔。用户則更需要看到示例、操作指南，和項目與其他軟件相配合的架構概述。</p><p><img src="https://opensource.com/sites/default/files/2023-03/different.perspectives.whiledocumenting.png" alt="圖片展示了編寫文檔時的不同視角"></p><p>總之，在創建任何流程之前，你必須確定你需要什麼：</p><ul><li><strong>關注的羣體：</strong> 包括開發者、集成商、管理員、用户、銷售、運營、高管</li><li><strong>專業水平：</strong> 要考慮到初級、中級和高級用户</li><li><strong>詳細程度：</strong> 既要有高層級的概述，也要有技術細節，所以要考慮如何呈現這些內容</li><li><strong>路徑和入口：</strong> 人們如何找到文檔，如何使用文檔</li></ul><p>當你思考這些問題時，它可以幫助你構建你想通過文檔傳達的信息的結構。它定義了文檔中必須包含的內容的清晰指標。</p><p>下面是如何圍繞文檔建立一個流程的方法。</p><h3 id="編碼約定" tabindex="-1">編碼約定 <a class="header-anchor" href="#編碼約定" aria-label="Permalink to “編碼約定”">​</a></h3><p>代碼本身應該有意義。文檔應通過良好的類名、文件名等來表達出來。通過思考以下內容，創建通用的編碼標準和自我註解的編碼過程：</p>',28)),i("ul",null,[t[2]||(t[2]=i("li",null,"變量命名約定",-1)),t[3]||(t[3]=i("li",null,"通過使用類、函數命名方案使名稱易於理解",-1)),i("li",null,[t[1]||(t[1]=l("避免深度嵌套，或 ",-1)),r(o,{href:"https://opensource.com/article/20/2/java-streams"},{default:e(()=>[...t[0]||(t[0]=[l("根本不嵌套",-1)])]),_:1})]),t[4]||(t[4]=i("li",null,"不要簡單地複製和粘貼代碼",-1)),t[5]||(t[5]=i("li",null,"不應使用長方法",-1)),t[6]||(t[6]=i("li",null,"避免使用幻數（改用常量）",-1)),t[7]||(t[7]=i("li",null,"使用提取的方法、變量等",-1)),t[8]||(t[8]=i("li",null,"使用有意義的目錄結構、模組、包和文件名",-1))]),t[28]||(t[28]=i("h3",{id:"開發時測試",tabindex:"-1"},[l("開發時測試 "),i("a",{class:"header-anchor",href:"#開發時測試","aria-label":"Permalink to “開發時測試”"},"​")],-1)),i("p",null,[t[10]||(t[10]=l("測試不僅僅是關於代碼應該如何工作。它還涉及如何使用 API、函數、方法等。編寫良好的測試可以揭示基本用例和邊緣用例。甚至還有一種 ",-1)),r(o,{href:"https://opensource.com/article/20/1/test-driven-development"},{default:e(()=>[...t[9]||(t[9]=[l("測試驅動開發",-1)])]),_:1}),t[11]||(t[11]=l(" 的實踐，專注於在代碼開發之前創建測試用例（應該測試什麼以及如何測試的分步場景）。",-1))]),t[29]||(t[29]=n('<h3 id="版本控制" tabindex="-1">版本控制 <a class="header-anchor" href="#版本控制" aria-label="Permalink to “版本控制”">​</a></h3><p>版本控制（即使是對文檔進行版本控制）可以幫助你跟蹤更改的邏輯。它可以幫助你回答為什麼這麼修改。</p><p>確保提交期間的註釋能解釋為什麼進行更改，而不是進行了哪些更改。</p><p>編寫文檔過程越吸引人，就會有更多的人蔘與其中，為它添加創造力和樂趣。你應該通過以下方式考慮文檔的可讀性：</p><ul><li>軟件代碼約定</li><li>圖表和圖形（也通過文字進行解釋）</li><li>思維導圖</li><li>概念圖</li><li>信息圖表</li><li>圖片（突出顯示重要的部分）</li><li>短視頻</li></ul><p>通過使用不同的交流方式，你可以提供更多的方式來參與文檔。這有助於防止誤解（不同的語言，不同的含義）和有助於通過不同的學習方式進行學習。</p><p>以下是一些用於創建文檔的軟件工具：</p><ul><li><strong>Javadoc、Doxygen、JsDoc 等：</strong> 許多語言都有自動化的文檔工具，以幫助捕獲代碼中的主要功能</li><li><strong>Web 鈎子和 CI/CD 引擎：</strong> 允許持續發佈文檔</li><li><strong>Restructured Text、Markdown、Asciidoc：</strong> 文件格式和處理引擎，幫助你從純文本文件中生成美觀且實用的文檔</li><li><strong>ReadTheDocs：</strong> 是一個可以和公共 Git 存儲庫聯動的文檔託管主機</li><li><strong>Draw.io、LibreOffice Draw、Dia：</strong> 製作圖表、圖形、思維導圖、路線圖、計劃、標準和指標等</li><li><strong>Peek、Asciinema：</strong> 記錄終端命令操作</li><li><strong>VokoscreenNG：</strong> 錄製屏幕和鼠標點擊操作</li></ul><h3 id="文檔很重要" tabindex="-1">文檔很重要 <a class="header-anchor" href="#文檔很重要" aria-label="Permalink to “文檔很重要”">​</a></h3><p>編寫文檔的過程和協議與項目本身同樣重要。最重要的是，它把項目的信息和項目的創造傳達到位，更加令人興奮。</p><p>快速進入項目和流程，以及瞭解一切是如何工作的，是文檔一個重要的功能。它有助於確保眾人持續參與。通過在團隊中構建一種“語言”，可以簡化流程，更清晰地理解所要做的事情。</p><p>文檔旨在傳達價值，即無論是通過團隊成員還是通過應用程序的用户的言行，來展示出某些東西。</p><p>要將這個過程視為一個連續的整體，並在其中融合使用溝通、流程和文檔的方式。</p><p><img src="https://opensource.com/sites/default/files/2023-03/doc.is_.aprocessofcommunication.png" alt="圖片展示了文檔作為一種溝通的過程"></p><p>文檔是一種溝通手段。</p><p><em>（題圖：MJ:document development illustration in high resolution, very detailed）</em></p><hr>',17)),i("p",null,[t[13]||(t[13]=l("via: ",-1)),r(o,{href:"https://opensource.com/article/23/3/community-documentation"},{default:e(()=>[...t[12]||(t[12]=[l("https://opensource.com/article/23/3/community-documentation",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=l("作者：",-1)),r(o,{href:"https://opensource.com/users/olga-merkulova"},{default:e(()=>[...t[14]||(t[14]=[l("Olga Merkulova",-1)])]),_:1}),t[19]||(t[19]=l(" 選題：",-1)),r(o,{href:"https://github.com/lkxed/"},{default:e(()=>[...t[15]||(t[15]=[l("lkxed",-1)])]),_:1}),t[20]||(t[20]=l(" 譯者：",-1)),r(o,{href:"https://github.com/alim0x"},{default:e(()=>[...t[16]||(t[16]=[l("alim0x",-1)])]),_:1}),t[21]||(t[21]=l(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[17]||(t[17]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[24]||(t[24]=l("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[22]||(t[22]=[l("LCTT",-1)])]),_:1}),t[25]||(t[25]=l(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:e(()=>[...t[23]||(t[23]=[l("Linux中國",-1)])]),_:1}),t[26]||(t[26]=l(" 榮譽推出",-1))])])}const h=s(m,[["render",d]]);export{C as __pageData,h as default};
